// src/pages/ContactPage.js
import { useState } from 'react';
import { Link } from 'react-router-dom';

function ContactPage() {
  const [darkMode, setDarkMode] = useState(false);
  const toggleTheme = () => setDarkMode(prev => !prev);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    setFormData({...formData, [e.target.name]: e.target.value});
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div className={darkMode ? 'dark-mode' : ''}>
      <header className="header">
        <h1>Contact Me</h1>
        <nav>
          <ul className="navList">
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/contact" className="active">Contact</Link></li>
            <li><Link to="/register">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className="theme-toggle" onClick={toggleTheme}>Toggle Dark/Light</button>

      {submitted ? (
        <p style={{textAlign: 'center', marginTop: '30px'}}>Thank you! We will get back to you soon.</p>
      ) : (
        <form onSubmit={handleSubmit} className="contact-form">
          <label>Name</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} required />

          <label>Email</label>
          <input type="email" name="email" value={formData.email} onChange={handleChange} required />

          <label>Message</label>
          <textarea name="message" rows="5" value={formData.message} onChange={handleChange} required></textarea>

          <input type="submit" value="Send Message" />
        </form>
      )}

      <footer className="footer">
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Personal Portfolio. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default ContactPage;
